let idc = 0;
export const FOODS = RAW.map(([name, diet, category, [servingLabel, servingGrams], values]) => {
  const per100 = {};
  NUTRIENT_KEYS.forEach((k, i) => { per100[k] = values[i] ?? 0; });
  return { id: `f${++idc}`, name, diet, category, servingLabel, servingGrams, per100 };
});

/**
 * Category order for the filter chips.
 *
 * Deliberately not alphabetical. The chip row scrolls horizontally on a phone,
 * so whatever sits past the fourth or fifth chip may as well not exist —
 * alphabetical put "Shakes & Desserts" fourteenth, which is the opposite of
 * useful for the one thing people are most likely to be looking up in a hurry.
 * Ordered by how often you actually reach for it instead.
 */
const CATEGORY_ORDER = [
  'Fast Food',
  'Coffee & Tea',
  'Deli & Grab-and-go',
  'Shakes & Desserts',
  'Prepared',
  'Grains',
  'Legumes',
  'Vegetables',
  'Fruits',
  'Dairy',
  'Meat & Poultry',
  'Eggs',
  'Fish & Seafood',
  'Beverages',
  'Snacks',
  'Nuts & Seeds',
  'Dairy Alternatives',
  'Fats & Oils',
  'Supplements',
];

export const FOOD_CATEGORIES = (() => {
  const present = new Set(FOODS.map((f) => f.category));
  const ordered = CATEGORY_ORDER.filter((c) => present.has(c));
  // Anything new that has not been placed yet still shows up, just at the end.
  const rest = [...present].filter((c) => !CATEGORY_ORDER.includes(c)).sort();
  return [...ordered, ...rest];
})();

/** Diet filter: what a person on `dietMode` is allowed to see. */
export function allowedDiets(dietMode, eatsEggs) {
  if (dietMode === 'vegan') return ['vegan'];
  if (dietMode === 'vegetarian') return eatsEggs ? ['vegan', 'vegetarian', 'egg'] : ['vegan', 'vegetarian'];
  return ['vegan', 'vegetarian', 'egg', 'nonveg'];
}

export function filterFoods(query, dietMode, eatsEggs, category) {
  const ok = allowedDiets(dietMode, eatsEggs);
  const q = query.trim().toLowerCase();
  return FOODS.filter(
    (f) =>
      ok.includes(f.diet) &&
      (!category || category === 'All' || f.category === category) &&
      (!q || f.name.toLowerCase().includes(q) || f.category.toLowerCase().includes(q))
  );
}

/** Scale a food's per-100 g profile to an arbitrary gram amount. */
export function nutrientsFor(food, grams) {
  const factor = grams / 100;
  const out = {};
  for (const k of NUTRIENT_KEYS) out[k] = (food.per100[k] || 0) * factor;
  return out;
}
